/* ========================================================================= */ /* 4. UI CONTROLLER AND APP INITIALIZER */ /* ========================================================================= */ /** * WKQUIZ UI CONTROLLER * Pure Vanilla JavaScript DOM Controller. * Handles rendering, events, dark mode, mobile drawer, search modal, and social sharing. */
class WKQuizUI { constructor(engine, config) { this.engine = engine; this.config = config || (typeof WKQUIZ_CONFIG !== "undefined" ? WKQUIZ_CONFIG : {}); this.currentQuestionData = null; this.isAnswered = false;
this.dom = { container: document.getElementById("wk-quiz-container"), darkModeToggle: document.getElementById("wk-dark-toggle"), mobileMenuBtn: document.getElementById("wk-menu-btn"), mobileDrawer: document.getElementById("wk-mobile-drawer"), searchBtn: document.getElementById("wk-search-btn"), searchModal: document.getElementById("wk-search-modal"), searchInput: document.getElementById("wk-search-input"), searchResults: document.getElementById("wk-search-results"), searchClose: document.getElementById("wk-search-close"), categoriesContainer: document.getElementById("wk-categories-grid") };
this.init(); }
init() { this._initTheme(); this._initEvents(); this._renderCategoriesGrid();
// Check if query param exists (e.g. ?quiz=nclex) const hasParams = this._checkUrlParams(); if (!hasParams && this.dom.container) { // Initialize a live quiz card immediately on page load without auto-scrolling this.startQuiz({ mode: "classic", category: "all" }, false); } }
/** * Theme Management (Zero-flash Dark Mode) */ _initTheme() { const savedTheme = localStorage.getItem("wkquiz_theme"); const prefersDark = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches; const initialTheme = savedTheme || (prefersDark ? "dark" : (this.config.theme ? this.config.theme.defaultTheme : "light"));
document.documentElement.setAttribute("data-theme", initialTheme); if (document.body) document.body.setAttribute("data-theme", initialTheme); this._updateThemeIcon(initialTheme); }
toggleTheme() { const currentTheme = document.documentElement.getAttribute("data-theme") || "light"; const nextTheme = currentTheme === "dark" ? "light" : "dark"; document.documentElement.setAttribute("data-theme", nextTheme); if (document.body) document.body.setAttribute("data-theme", nextTheme); localStorage.setItem("wkquiz_theme", nextTheme); this._updateThemeIcon(nextTheme); }
_updateThemeIcon(theme) { if (this.dom.darkModeToggle) { this.dom.darkModeToggle.innerHTML = theme === "dark" ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>' : '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>'; } }
/** * Global Event Listeners */ _initEvents() { // Theme Toggle if (this.dom.darkModeToggle) { this.dom.darkModeToggle.addEventListener("click", () => this.toggleTheme()); }
// Mobile Menu if (this.dom.mobileMenuBtn && this.dom.mobileDrawer) { this.dom.mobileMenuBtn.addEventListener("click", () => { this.dom.mobileDrawer.classList.toggle("open"); }); }
// Search Modal if (this.dom.searchBtn && this.dom.searchModal) { this.dom.searchBtn.addEventListener("click", () => this.openSearch()); } if (this.dom.searchClose && this.dom.searchModal) { this.dom.searchClose.addEventListener("click", () => this.closeSearch()); } if (this.dom.searchModal) { this.dom.searchModal.addEventListener("click", (e) => { if (e.target === this.dom.searchModal) this.closeSearch(); }); } if (this.dom.searchInput) { this.dom.searchInput.addEventListener("input", (e) => this.handleSearch(e.target.value)); }
// Keyboard Shortcuts (Esc to close search, / to open search) document.addEventListener("keydown", (e) => { if (e.key === "Escape" && this.dom.searchModal && this.dom.searchModal.classList.contains("open")) { this.closeSearch(); } if (e.key === "/" && document.activeElement.tagName !== "INPUT" && document.activeElement.tagName !== "TEXTAREA") { e.preventDefault(); this.openSearch(); } });
// Global CTA handlers document.addEventListener("click", (e) => { const target = e.target.closest("[data-action]"); if (!target) return;
const action = target.getAttribute("data-action"); const category = target.getAttribute("data-category"); const mode = target.getAttribute("data-mode");
if (action === "start-random") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.startQuiz({ mode: "classic", category: "all" }, true); } else if (action === "start-daily") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.startQuiz({ mode: "daily", category: "all" }, true); } else if (action === "start-category") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.startQuiz({ mode: "classic", category: category || "all" }, true); } else if (action === "start-mode") { e.preventDefault(); if (this.dom.mobileDrawer) this.dom.mobileDrawer.classList.remove("open"); this.startQuiz({ mode: mode || "classic", category: category || "all" }, true); } else if (action === "restart-quiz") { e.preventDefault(); this.startQuiz({ mode: this.engine.mode || "classic", category: this.engine.currentQuiz ? this.engine.currentQuiz.category : "all" }, true); } }); }
/** * Check URL query parameters on load (e.g. ?quiz=nclex or ?mode=daily) */ _checkUrlParams() { if (typeof window === "undefined" || !window.location.search) return false; const params = new URLSearchParams(window.location.search); const category = params.get("quiz") || params.get("category"); const mode = params.get("mode");
