/* ========================================================================= */ /* 5. AUTO-INITIALIZE APP ROBUSTLY ON PAGE LOAD */ /* ========================================================================= */ (function() { function initWKQuizPlatform() { if (window.__wkQuizInitialized) return; window.__wkQuizInitialized = true; try { if (typeof WKQuizEngine !== 'undefined' && typeof WKQuizUI !== 'undefined') { var bank = (typeof wkQuizBank !== 'undefined' && wkQuizBank) ? wkQuizBank : new WKQuizQuestionBank(WKQUIZ_QUESTIONS); var cfg = (typeof WKQUIZ_CONFIG !== 'undefined' && WKQUIZ_CONFIG) ? WKQUIZ_CONFIG : {}; var engine = new WKQuizEngine({ bank: bank, config: cfg.quiz || {} }); window.wkQuizApp = new WKQuizUI(engine, cfg); console.log('[WKQuiz] Platform successfully initialized.'); } } catch (e) { console.error('[WKQuiz] Initialization error:', e); } }
